create table if not exists public.editorial_articles(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,description text not null,pillar text not null,thesis text not null,intended_audience text not null,review_status text not null default 'idea' check(review_status in('idea','research','draft','evidence_check','technical_review','editorial_review','seo_ux_review','approved','published','archived')),methodology_version text not null,evidence_version text not null,reviewed_at timestamptz,updated_at timestamptz not null default now(),published_at timestamptz,created_at timestamptz not null default now());
alter table public.editorial_articles enable row level security;grant select on public.editorial_articles to anon,authenticated;create policy "published articles are public" on public.editorial_articles for select to anon,authenticated using(review_status='published');
create table if not exists public.editorial_sources(id uuid primary key default gen_random_uuid(),article_id uuid not null references public.editorial_articles(id) on delete cascade,citation text not null,source_url text,source_type text not null,claim_scope text not null,verified_at timestamptz,created_at timestamptz not null default now());
alter table public.editorial_sources enable row level security;grant select on public.editorial_sources to anon,authenticated;create policy "sources follow published articles" on public.editorial_sources for select to anon,authenticated using(exists(select 1 from public.editorial_articles a where a.id=article_id and a.review_status='published'));
create index if not exists editorial_articles_pillar_status_idx on public.editorial_articles(pillar,review_status);create index if not exists editorial_sources_article_idx on public.editorial_sources(article_id);
create table if not exists public.editorial_revisions(id uuid primary key default gen_random_uuid(),article_id uuid not null references public.editorial_articles(id) on delete cascade,revision_number integer not null,summary text not null,review_stage text not null,created_at timestamptz not null default now(),unique(article_id,revision_number));
alter table public.editorial_revisions enable row level security;revoke all on public.editorial_revisions from anon,authenticated;
